using namespace opensim;using services::Caps;
std::string hex(std::string_view s){std::string r;for(unsigned char c:s){r+="0123456789abcdef"[c>>4];r+="0123456789abcdef"[c&15];}return r;}
template<class F>std::string run(F f){try{return f();}catch(const std::exception&){return "EX";}}
struct Context{std::string trace,fail;void log(const std::string& s){trace+=s+";";if(s==fail)throw std::runtime_error("injected");}};
struct Event:services::CapabilityActivation{Context& c;bool active=false;explicit Event(Context& ctx):c(ctx){}void reset()override{c.log("reset");active=false;}void set()override{c.log("set");active=true;}bool wait(int ms)override{c.log("wait"+std::to_string(ms));return active;}void dispose()override{c.log("dispose");}};
struct Handler:server::CapabilityStreamHandler,server::CapabilitySimpleHandler{std::string value;explicit Handler(std::string s):value(std::move(s)){}std::optional<std::string> path()const override{return value;}std::string method()const override{return "POST";}network::HttpResponse handle(const network::HttpRequest&)override{return {};}};
struct Listener:services::CapabilityRuntimeListener{Context& c;bool ssl;std::string label;Listener(Context& ctx,bool s,std::string l):c(ctx),ssl(s),label(std::move(l)){}bool use_ssl()const override{c.log(label+".ssl");return ssl;}std::uint32_t port()const override{c.log(label+".port");return 8080;}std::uint32_t ssl_port()const override{c.log(label+".sslport");return label=="L"?9443:8443;}std::optional<std::string> ssl_common_name()const override{c.log(label+".name");return label=="L"?"listener":"main";}void add_stream(const std::shared_ptr<server::CapabilityStreamHandler>&)override{c.log("stream+");}void remove_stream(const std::string& m,const std::optional<std::string>&)override{c.log("stream-"+m);}void add_simple(const std::shared_ptr<server::CapabilitySimpleHandler>&)override{c.log("simple+");}void remove_simple(const std::optional<std::string>&)override{c.log("simple-");}void add_poll(const std::shared_ptr<services::CapabilityPollHandler>&)override{c.log("poll+");}void remove_poll(const std::optional<std::string>&)override{c.log("poll-");}};
std::string dump(const services::CapabilityPaths& map){std::vector<std::string> a;for(const auto& e:map)a.push_back(hex(e.first)+":"+(e.second?hex(*e.second):"-"));std::sort(a.begin(),a.end());std::string r;for(const auto& s:a)r+=s+",";return r;}
int main(){std::string line;while(std::getline(std::cin,line)){std::istringstream in(line);int ssl,mainssl,setup,action,failure;in>>ssl>>mainssl>>setup>>action>>failure;Context ctx;auto l=std::make_shared<Listener>(ctx,ssl!=0,"L");std::shared_ptr<Listener> main=mainssl==2?nullptr:std::make_shared<Listener>(ctx,mainssl!=0,"M");std::shared_ptr<Caps> caps;auto poll=std::make_shared<services::CapabilityPollHandler>();poll->url="/poll<&'\"";auto h=std::make_shared<Handler>("/normal");auto simple=std::make_shared<Handler>("/simple");auto result=run([&]{caps=std::make_shared<Caps>(l,"host&",9000,"seed",framework::Uuid("00000000-0000-0000-0000-000000000001"),"region",[&]()->std::shared_ptr<services::CapabilityRuntimeListener>{ctx.log("main");return main;},std::make_shared<Event>(ctx),[&](const std::string& s){ctx.log("error:"+hex(s));});caps->register_handler("SEED",h);if(setup&2)caps->register_simple("X",simple,false);if(setup&1)caps->register_handler("X",h);if(setup&4)caps->register_poll("X",poll);if(setup&8)caps->register_external("X","https://external/?<&'\"");caps->flags=Caps::PBR;ctx.trace.clear();ctx.fail=std::vector<std::string>{"","stream-POST","stream-PUT","simple-","poll-","poll+","dispose","set"}.at(failure);switch(action){case 1:caps->register_poll("X",poll);break;case 2:caps->register_external("X","second");break;case 3:caps->deregister_handlers();break;case 4:caps->dispose();break;case 5:caps->activate();return caps->wait_for_activation()?std::string("1"):std::string("0");case 6:return caps->wait_for_activation()?std::string("1"):std::string("0");case 7:caps->register_poll("X",nullptr);break;case 8:caps->register_external(std::nullopt,"bad");break;case 9:caps->external_handlers()["X"]=std::nullopt;break;case 10:if(main)main->ssl=!main->ssl;break;case 11:caps->dispose();caps->activate();break;case 12:{auto copy=caps->get_poll_handlers();copy.erase("X");poll->url=std::nullopt;break;}case 13:caps->register_handler("X",nullptr);break;case 14:caps->dispose(false);caps->dispose();break;case 15:{auto saved=caps->flags;caps->flags=0;saved|=Caps::SentSeeds;caps->flags=saved;break;}}return std::string("OK");});
if(!caps){std::cout<<result<<"|"<<hex(ctx.trace)<<"\n";continue;}Caps::Requested req={"X","SEED","missing","X"};auto all=run([&]{return dump(caps->details(true,nullptr));});auto requested=run([&]{return dump(caps->details(true,&req));});std::string xml;auto xmlstatus=run([&]{caps->append_details_xml(&req,&xml);return std::string("OK");});auto nullxml=run([&]{caps->append_details_xml(nullptr,nullptr);return std::string("OK");});std::shared_ptr<services::CapabilityPollHandler> got;bool has=caps->try_get_poll("X",got);auto metadata=run([&]{auto host=caps->host_name();auto port=caps->port();auto base=caps->base_url();auto ssl=caps->ssl_caps();auto common=caps->ssl_common_name();return hex(host.value_or(""))+":"+std::to_string(port)+":"+hex(base.value_or(""))+":"+(ssl?"1":"0")+":"+hex(common.value_or(""));});std::cout<<result<<"|"<<all<<"|"<<requested<<"|"<<xmlstatus<<":"<<hex(xml)<<"|"<<nullxml<<"|"<<has<<":"<<(got==poll?1:0)<<"|"<<caps->flags<<"|"<<metadata<<"|"<<hex(ctx.trace)<<"\n";
}}
